solution:
a, b, c = map(int, input().split())
if a == 0:
    if b != 0:
        print(1)
    elif c == 0:
        print("INF")
    else:
        print(0)
else:
    d = b * b - 4 * a * c
    if d > 0:
        print(2)
    elif d == 0:
        print(1)
    else:
        print(0)

